// REPORTS-P1-A: stable identity for case sub-items (cases.items[].key).
//
// Keys are generated by the server and never inferred from array position. Delivery
// records may reference a key, so every authorized items write reconciles keys
// deliberately against the stored snapshot:
//   1. An incoming key must already exist on this case and appear at most once.
//   2. A keyless incoming item (older screens drop unknown fields) adopts the key of an
//      unclaimed stored item with identical content (an unchanged item keeps identity).
//   3. Otherwise it may adopt the key of the single unclaimed, unlinked stored item with
//      the same name when that name is also unique in the request (an edited item that
//      no delivery references yet). Linked keys are never guessed.
//   4. Remaining keyless items get a fresh key.
// A key referenced by a non-voided delivery that ends up unclaimed means the request
// removed or replaced delivery evidence ambiguously: the whole write is rejected.
import crypto from 'node:crypto';
import { CaseEditError } from './caseJsonEdits.js';

export const ITEM_KEY_PATTERN = /^[A-Za-z0-9_-]{8,64}$/;
export const newItemKey = () => crypto.randomUUID();

const isItem = value => value !== null && typeof value === 'object' && !Array.isArray(value);
function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (!isItem(value)) return value;
  return Object.fromEntries(Object.keys(value).sort().filter(k => value[k] !== undefined).map(k => [k, canonical(value[k])]));
}
// Content equality must not depend on how a write path filled optional fields: PATCH /items
// applies itemSchema defaults (type/owner '' and status 尚未製作) and older screens send null for
// unset optional fields, while create stores the client object as given. Compare both sides
// under the same normalization: schema defaults applied, null/undefined/[] optional values dropped.
const ITEM_DEFAULTS = { type: '', owner: '', status: '尚未製作' };
export function normalizedItemContent(item) {
  const { key, ...rest } = item;
  const filled = { ...ITEM_DEFAULTS, ...Object.fromEntries(Object.entries(rest).filter(([, v]) => v !== undefined)) };
  for (const [field, fallback] of Object.entries(ITEM_DEFAULTS)) if (filled[field] === null) filled[field] = fallback;
  for (const [field, value] of Object.entries(filled)) if (value === null || (Array.isArray(value) && value.length === 0)) delete filled[field];
  return JSON.stringify(canonical(filled));
}
const contentOf = normalizedItemContent;

// New cases start without stored keys, so any client-supplied key is foreign.
export function assignNewItemKeys(items) {
  if (!Array.isArray(items)) return items;
  return items.map(item => {
    if (!isItem(item)) return item;
    if (item.key !== undefined) throw new CaseEditError(422, 'item_key_foreign', '新案件的子案件不可帶入既有識別碼，請移除後重新送出。');
    return { ...item, key: newItemKey() };
  });
}

export function reconcileItemKeys(storedItems, incomingItems, linkedKeys = new Set()) {
  const stored = (Array.isArray(storedItems) ? storedItems : []).filter(it => isItem(it) && typeof it.key === 'string' && ITEM_KEY_PATTERN.test(it.key));
  const byKey = new Map(stored.map(it => [it.key, it]));
  const seen = new Set();
  for (const item of incomingItems) {
    if (item.key === undefined || item.key === null) continue;
    if (typeof item.key !== 'string' || !ITEM_KEY_PATTERN.test(item.key)) throw new CaseEditError(422, 'item_key_invalid', '子案件識別碼格式不正確，請重新載入後再編輯。');
    if (seen.has(item.key)) throw new CaseEditError(422, 'item_key_duplicate', '同一個子案件識別碼出現兩次，請重新載入後再編輯。');
    if (!byKey.has(item.key)) throw new CaseEditError(422, 'item_key_foreign', '子案件識別碼不屬於此案件，請重新載入後再編輯。');
    seen.add(item.key);
  }
  const claimed = new Set(seen);
  const result = incomingItems.map(item => (item.key ? { ...item } : { ...item, key: null }));
  // Tier 1: identical content keeps its identity (unchanged items from older screens).
  for (const item of result) {
    if (item.key) continue;
    const content = contentOf(item);
    const match = stored.find(it => !claimed.has(it.key) && contentOf(it) === content);
    if (match) { item.key = match.key; claimed.add(match.key); }
  }
  // Tier 2: unique same-name match, only for keys no delivery references.
  const nameCount = new Map();
  for (const item of result) if (!item.key) nameCount.set(item.n, (nameCount.get(item.n) || 0) + 1);
  for (const item of result) {
    if (item.key || nameCount.get(item.n) !== 1) continue;
    const candidates = stored.filter(it => !claimed.has(it.key) && it.n === item.n);
    if (candidates.length === 1 && !linkedKeys.has(candidates[0].key)) { item.key = candidates[0].key; claimed.add(item.key); }
  }
  for (const item of result) if (!item.key) item.key = newItemKey();
  const lost = [...linkedKeys].filter(key => byKey.has(key) && !claimed.has(key));
  if (lost.length) {
    const names = lost.map(key => byKey.get(key).n).filter(Boolean).slice(0, 5).join('、');
    throw new CaseEditError(409, 'linked_item_removed', `子案件「${names}」已有交付紀錄，不能移除或在未保留識別碼下修改；請重新載入後再編輯。`);
  }
  return result;
}
